// Define vendors
const vendors = ['Linear', 'Notion', 'Figma', 'Vercel', 'Intercom', 'Retool', 'Airtable', 'Loom'];

// Initialize results
const results = {};

// Process each vendor
vendors.forEach(vendor => {
  // Use firecrawl-map to find subprocessor list page
  const mapResult = await tools.firecrawl.map({
    url: `${vendor.toLowerCase()}.com`,
    search: 'subprocessors'
  });

  // Extract the first matching URL
  const subprocessorUrl = mapResult?.matches?.[0]?.url;

  if (subprocessorUrl) {
    // Use firecrawl-scrape to get page content
    const scrapeResult = await tools.firecrawl.scrape({
      url: subprocessorUrl
    });

    // Parse content for subprocessor data
    const parser = new DOMParser();
    const doc = parser.parseFromString(scrapeResult.content, 'text/html');
    const subprocessors = Array.from(doc.querySelectorAll('.subprocessor-list li'));
    const lastUpdate = doc.querySelector('.last-updated')?.textContent?.trim();

    results[vendor] = {
      url: subprocessorUrl,
      count: subprocessors.length,
      outsideUsEu: subprocessors
        .map(li => li.textContent.trim())
        .filter(name => !/\b(?:US|Canada|UK|EU)\b/.test(name)),
      lastUpdated: lastUpdate
    };
  } else {
    results[vendor] = {
      error: 'Subprocessor list not found'
    };
  }
});

// Format output
results;

